module ops(input [3:0] a, input [3:0] b, output [3:0] band, output lor, output rand_all, output [3:0] big);
  assign band = a & b;
  assign lor = a || b;
  assign rand_all = &a;
  assign big = (a > b) ? a : b;
endmodule

module ops_tb;
  reg [3:0] a, b; wire [3:0] band, big; wire lor, rand_all; integer errors;
  ops dut(.a(a), .b(b), .band(band), .lor(lor), .rand_all(rand_all), .big(big));
  initial begin
    errors = 0; a = 4'b1010; b = 4'b0101; #1;
    $display("and=%b or=%b all=%b big=%d", band, lor, rand_all, big);
    if (band !== 4'b0000 || lor !== 1'b1 || rand_all !== 1'b0 || big !== 4'd10) errors = errors + 1;
    a = 4'b1111; b = 4'b0111; #1;
    if (rand_all !== 1'b1 || big !== 4'd15) errors = errors + 1;
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

