module dff_sync(input clk, input rst, input d, output reg q);
  always @(posedge clk) begin
    if (rst) q <= 1'b0;
    else q <= d;
  end
endmodule

module dff_sync_tb;
  reg clk, rst, d; wire q; integer errors;
  dff_sync dut(.clk(clk), .rst(rst), .d(d), .q(q));
  initial clk = 0;
  always #5 clk = ~clk;
  initial begin
    errors = 0; rst = 1; d = 1;
    @(posedge clk); #1;
    if (q !== 1'b0) errors = errors + 1;
    rst = 0; d = 1;
    @(posedge clk); #1;
    $display("q=%b", q);
    if (q !== 1'b1) errors = errors + 1;
    d = 0;
    @(posedge clk); #1;
    if (q !== 1'b0) errors = errors + 1;
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

module swap(input clk, input load, input [3:0] ia, input [3:0] ib, output reg [3:0] a, output reg [3:0] b);
  always @(posedge clk) begin
    if (load) begin
      a <= ia;
      b <= ib;
    end else begin
      a <= b;
      b <= a;
    end
  end
endmodule

module swap_tb;
  reg clk, load; reg [3:0] ia, ib; wire [3:0] a, b; integer errors;
  swap dut(.clk(clk), .load(load), .ia(ia), .ib(ib), .a(a), .b(b));
  initial clk = 0;
  always #5 clk = ~clk;
  initial begin
    errors = 0; load = 1; ia = 4'd3; ib = 4'd9;
    @(posedge clk); #1; load = 0;
    @(posedge clk); #1;
    $display("a=%0d b=%0d", a, b);
    if (a !== 4'd9 || b !== 4'd3) errors = errors + 1;
    @(posedge clk); #1;
    if (a !== 4'd3 || b !== 4'd9) errors = errors + 1;
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

