module up_counter(input clk, input rst, output reg [3:0] count);
  always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else count <= count + 4'd1;
  end
endmodule

module up_counter_tb;
  reg clk, rst; wire [3:0] count; integer errors, i;
  up_counter dut(.clk(clk), .rst(rst), .count(count));
  initial clk = 0;
  always #5 clk = ~clk;
  initial begin
    errors = 0; rst = 1; #12; rst = 0;
    for (i = 1; i <= 10; i = i + 1) begin
      @(posedge clk); #1;
      if (count !== i) errors = errors + 1;
    end
    $display("count=%0d", count);
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

