module det101(input clk, input rst, input x, output y);
  parameter S0 = 2'd0, S1 = 2'd1, S2 = 2'd2;
  reg [1:0] state, next;
  always @(posedge clk) begin
    if (rst) state <= S0;
    else state <= next;
  end
  always @(*) begin
    case (state)
      S0: next = x ? S1 : S0;
      S1: next = x ? S1 : S2;
      S2: next = x ? S1 : S0;
      default: next = S0;
    endcase
  end
  assign y = (state == S2) & x;
endmodule

module det101_tb;
  reg clk, rst, x; wire y; integer i, hits; reg [7:0] pattern;
  det101 dut(.clk(clk), .rst(rst), .x(x), .y(y));
  initial begin
    clk = 0; rst = 1; x = 0; hits = 0; pattern = 8'b10110101;
    #2 clk = 1; #2 clk = 0; rst = 0;
    for (i = 7; i >= 0; i = i - 1) begin
      x = pattern[i]; #1;
      if (y) begin hits = hits + 1; $display("101 found at bit %0d", i); end
      #1 clk = 1; #2 clk = 0;
    end
    if (hits == 3) $display("PASS"); else $display("FAIL hits=%0d", hits);
    $finish;
  end
endmodule
